<template>
  <section v-if="instance" class="surface" v-loading="loading"><div class="toolbar"><div><h2>推送渠道</h2><p>渠道凭据引用密钥托管中的别名，不显示真实凭据。</p></div><el-button v-if="canManage" type="primary" @click="openCreate">添加渠道</el-button></div><el-table :data="channels"><el-table-column prop="name" label="名称" min-width="140"/><el-table-column prop="type" label="类型" width="110"/><el-table-column prop="endpoint" label="地址" min-width="220" show-overflow-tooltip/><el-table-column prop="secretAlias" label="密钥别名" min-width="130"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><template v-if="canManage"><el-button link @click="edit(row)">编辑</el-button><el-button link :type="row.enabled?'warning':'primary'" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table><el-empty v-if="!channels.length&&!loading" description="暂无推送渠道"/>
    <el-divider/><div class="toolbar"><div><h2>投递日志</h2><p>每个渠道独立记录投递结果和重试状态。</p></div></div><el-table :data="deliveries"><el-table-column prop="channelId" label="渠道 ID" min-width="160"/><el-table-column prop="status" label="状态" width="110"/><el-table-column prop="attemptCount" label="尝试" width="80"/><el-table-column prop="error" label="错误" min-width="180" show-overflow-tooltip/><el-table-column label="时间" min-width="170"><template #default="{row}">{{new Date(row.createTime).toLocaleString()}}</template></el-table-column></el-table>
    <el-dialog v-model="dialog" :title="editing?'编辑渠道':'添加渠道'" width="520px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item v-if="!editing" label="类型"><el-select v-model="form.type"><el-option label="Webhook" value="webhook"/><el-option label="钉钉" value="dingtalk"/><el-option label="飞书" value="feishu"/><el-option label="企业微信" value="wechat_work"/></el-select></el-form-item><el-form-item label="地址"><el-input v-model="form.endpoint"/></el-form-item><el-form-item label="密钥别名（可选）"><el-input v-model="form.secretAlias"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import {ref,watch}from 'vue';import {ElMessage,ElMessageBox}from 'element-plus';import type {DeveloperProductInstanceDto,DeveloperPushChannelDto,DeveloperPushDeliveryDto}from '@/client/types.gen';import{developerProductService}from '@/service/developerProductService';const props=defineProps<{instance?:DeveloperProductInstanceDto;canManage:boolean}>();const loading=ref(false),channels=ref<DeveloperPushChannelDto[]>([]),deliveries=ref<DeveloperPushDeliveryDto[]>([]),dialog=ref(false),editing=ref<DeveloperPushChannelDto>(),form=ref({name:'',type:'webhook' as 'webhook'|'dingtalk'|'feishu'|'wechat_work',endpoint:'',secretAlias:''});const load=async()=>{if(!props.instance)return;loading.value=true;try{const [nextChannels,nextDeliveries]=await Promise.all([developerProductService.listPushChannelResources(props.instance.id),developerProductService.listPushDeliveryResources(props.instance.id)]);channels.value=nextChannels;deliveries.value=nextDeliveries}finally{loading.value=false}};const openCreate=()=>{editing.value=undefined;form.value={name:'',type:'webhook',endpoint:'',secretAlias:''};dialog.value=true};const edit=(row:DeveloperPushChannelDto)=>{editing.value=row;form.value={name:row.name,type:row.type as typeof form.value.type,endpoint:row.endpoint,secretAlias:row.secretAlias||''};dialog.value=true};const save=async()=>{if(!props.instance)return;if(editing.value)await developerProductService.updatePushChannelResource(props.instance.id,editing.value.id,{name:form.value.name,endpoint:form.value.endpoint,secretAlias:form.value.secretAlias||null});else await developerProductService.createPushChannelResource(props.instance.id,{...form.value,secretAlias:form.value.secretAlias||undefined});dialog.value=false;await load();ElMessage.success('渠道已保存')};const toggle=async(row:DeveloperPushChannelDto)=>{if(!props.instance)return;await developerProductService.updatePushChannelResource(props.instance.id,row.id,{enabled:!row.enabled});await load()};const remove=async(row:DeveloperPushChannelDto)=>{if(!props.instance)return;await ElMessageBox.confirm(`删除推送渠道 ${row.name} 后无法恢复。`,'删除渠道',{type:'warning'});await developerProductService.deletePushChannelResource(props.instance.id,row.id);await load();ElMessage.success('渠道已删除')};watch(()=>props.instance?.id,load,{immediate:true})
</script><style scoped>.toolbar{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.toolbar h2{margin:0 0 6px;font-size:17px}.toolbar p{margin:0;color:var(--el-text-color-secondary)}</style>
